<script setup>
import { computed } from 'vue';import { useRouter } from 'vue-router';import BottomNav from '@/components/common/BottomNav.vue';import ExchangeTicket from '@/components/exchange/ExchangeTicket.vue';import { useExchangeStore } from '@/stores/exchange';import { useTravelStore } from '@/stores/travel'
const router=useRouter();const exchange=useExchangeStore();const travel=useTravelStore();const tabs=[['rate','환율'],['alerts','환율 알림'],['banks','근처 은행']]
function move(tab){if(tab==='alerts')router.push('/exchange/alerts');else if(tab==='banks')router.push('/exchange/banks')}
const format=(v,d=2)=>Number(v||0).toLocaleString('ko-KR',{maximumFractionDigits:d})
const currencyByCountry={FR:'EUR',DE:'EUR',CH:'CHF',JP:'JPY',HK:'HKD'}
const majorCurrencies=computed(()=>[...new Set(travel.selectedCountryCodes.map(code=>currencyByCountry[code]).filter(Boolean))].map(code=>exchange.getCurrency(code)).filter(Boolean))
const sentAmount=computed(()=>format(exchange.krwAmount,0))
const receivedAmount=computed(()=>format(exchange.foreignAmount))
const amountClass=value=>({compact:String(value).length>10,tiny:String(value).length>14})
function updateKrw(event){const digits=event.target.value.replace(/[^0-9]/g,'').slice(0,16);exchange.krwAmount=Number(digits)||0;event.target.value=format(exchange.krwAmount,0)}
</script>
<template><main class="page"><div class="shell"><header><h1>환율·환전</h1></header><nav><button v-for="tab in tabs" :key="tab[0]" :class="{active:tab[0]==='rate'}" @click="move(tab[0])">{{ tab[1] }}</button></nav><ExchangeTicket :title="`${exchange.selectedCurrency.flag} ${exchange.selectedCurrency.code} ${format(exchange.selectedCurrency.rate)}원`" :subtitle="`어제보다 ${exchange.selectedCurrency.change>0?'▲':'▼'} ${format(Math.abs(exchange.selectedCurrency.change))}원 · 환전 계산 03:00`"/><section class="calculator"><h2>빠른 환율 계산</h2><div><label>보내는 금액<input :value="sentAmount" :class="amountClass(sentAmount)" inputmode="numeric" aria-label="보내는 금액" @input="updateKrw"><b>KRW</b></label><span>→</span><label>받는 금액<strong :class="amountClass(receivedAmount)">{{ receivedAmount }}</strong><b>{{ exchange.selectedCode }}</b></label></div><button @click="router.push(`/exchange/currencies/${exchange.selectedCode}`)">환율 계산 더보기 ›</button></section><div class="title"><h2>주요 통화</h2><button type="button" @click="router.push('/exchange/currencies')">전체 보기</button></div><section v-if="majorCurrencies.length" class="currencies"><button v-for="item in majorCurrencies" :key="item.code" @click="exchange.selectedCode=item.code;router.push(`/exchange/currencies/${item.code}`)"><span>{{ item.flag }}</span><b>{{ item.code }}</b><strong>{{ format(item.rate) }}원</strong><em :class="{up:item.change>0}">{{ item.change>0?'▲':'▼' }} {{ format(Math.abs(item.change)) }}</em><i>›</i></button></section><section v-else class="empty"><b>등록된 여행 목표가 없어요.</b><p>여행 목표를 등록하면 해당 국가의 통화를 바로 확인할 수 있어요.</p><button type="button" @click="router.push('/travel/register')">여행 목표 등록하기</button></section><BottomNav/></div></main></template>
