r:#a2adbc;font-size:17px;font-style:normal}.empty{padding:22px 14px;border:1px dashed #cbd5e1;border-radius:14px;background:#fff;text-align:center}.empty b{font-size:11px}.empty p{margin-top:6px;color:#94a3b8;font-size:8px;line-height:1.5}.empty button{margin-top:12px;padding:8px 12px;border-radius:8px;background:#173f8d;color:#fff;font-size:8px;font-weight:900}
